// アポロ17号（1972年12月）の史跡。タウルス・リットロウ谷のレース場（SITES.taurus）で、ローバーで訪ねて集める。
// 位置は Haase ほか (2018) の測量点（APOLLO17_CONTROLPOINTS_2018.TAB）を、着陸地点（原点 20.18629N 30.76622E）からの
// m に直したもの（x 東・z 南）。月面車の最後の駐車位置だけは、3回目の船外活動の終わりの走行記録からのおおよそ。
// 走行の道すじ APOLLO17_TRAVERSE は同じ論文の APOLLO17_TRAVERSE_2018.SHP（25 m ごとに間引き）。

export type HistoricKind = 'lm' | 'flag' | 'lrv' | 'alsep' | 'station'

export type Historic = {
  id: string
  kind: HistoricKind
  x: number
  z: number
  /** 近づくと記録される距離（m） */
  r: number
  /** 図鑑の番号の横に出す絵文字 */
  icon: string
  /** 観測点の番号（観測点だけ） */
  no?: number
  /** 観測点の目印の特別な物：オレンジの土・割れた大岩・大きな岩 */
  feature?: 'orange' | 'split' | 'boulders'
  /** その場所の当時の写真（説明と出典は i18n の photoCaption・photoCredit）。src は画像、page は出典のページ */
  photo?: { src: string; page: string }
}

/** Historic の文言（日本語は src/i18n/apollo17.ja.ts、英語は apollo17.en.ts） */
export type HistoricText = {
  name: string
  /** いつ（船外活動の何回目か） */
  when: string
  story: string
  /** 写真の説明（photo がある史跡だけ） */
  photoCaption?: string
  /** 写真の出典 */
  photoCredit?: string
}

